2|use tiktoken_rs::bpe_for_model;
3|use tokenizers::Tokenizer as TokenizerImpl;
4|use tracing::debug;
5|
6|/// Tokenizer for prompt encoding.
7|///
8|/// supports BPE models (GPT-2, GPT-3) and tokenizers library.
9|pub struct Tokenizer {
10|    pub model: String,
11|    pub tokenizer: Option<TokenizerImpl>,
12|}
13|
14|impl Tokenizer {
15|    pub fn new(model: impl Into<String>) -> Self {
16|        Self {
17|            model: model.into(),
18|            tokenizer: None,
19|        }
20|    }
21|
22|    /// Initialize BPE from model name.
23|    pub fn init_bpe(&mut self) -> Result<(), RunnerError> {
24|        let _bpe = bpe_for_model(&self.model)
25|            .map_err(|e: anyhow::Error| RunnerError::Tokenizer(e.to_string()))?;
26|        debug!(model = %self.model, "Tokenizer: BPE initialized");
27|        Ok(())
28|    }
29|
30|    /// Encode prompt to token IDs.
31|    pub fn encode(&self, prompt: &str) -> Result<Vec<u32>, RunnerError> {
32|        if let Some(ref tok) = self.tokenizer {
33|            tok.encode(prompt, false)
34|                .map_err(|e: Box<dyn std::error::Error + Send + Sync>| {
35|                    RunnerError::Tokenizer(e.to_string())
36|                })
37|                .map(|e| e.get_ids().to_vec())
38|        } else {
39|            Err(RunnerError::Tokenizer(
40|                "tokenizer not initialized".to_string(),
41|            ))
42|        }
43|    }
44|
45|    /// Decode token IDs to text.
46|    pub fn decode(&self, tokens: &[u32]) -> Result<String, RunnerError> {
47|        if let Some(ref tok) = self.tokenizer {
48|            tok.decode(tokens, false)
49|                .map_err(|e: Box<dyn std::error::Error + Send + Sync>| {
50|                    RunnerError::Tokenizer(e.to_string())
51|                })
52|        } else {
53|            Err(RunnerError::Tokenizer(
54|                "tokenizer not initialized".to_string(),
55|            ))
56|        }
57|    }
58|
59|    /// Get token count.
60|    pub fn token_count(&self, prompt: &str) -> Result<usize, RunnerError> {
61|        if let Some(ref tok) = self.tokenizer {
62|            Ok(tok
63|                .encode(prompt, false)
64|                .map_err(|e: Box<dyn std::error::Error + Send + Sync>| {
65|                    RunnerError::Tokenizer(e.to_string())
66|                })?
67|                .get_ids()
68|                .len())
69|        } else {
70|            Err(RunnerError::Tokenizer(
71|                "tokenizer not initialized".to_string(),
72|            ))
73|        }
74|    }
