229|    println!("✓ Loaded {} transformer layers", layers.len());
230|
231|    // Load final norm
232|    let final_norm = pesti_runner::transformer_cpu::RmsNorm::new(1e-5, embed_dim);
233|
234|    // Load output projection - GGUF stores as [embed_dim, vocab_size] (transposed!)
235|    let output_data = weights
236|        .tensors
237|        .get("output.weight")
238|        .ok_or("Missing output.weight")?;
239|
240|    let (in_feat, out_feat) = weights.tensor_shape("output.weight");
241|    println!(
242|        "DEBUG: output.weight shape from GGUF: [{}x{}]",
243|        in_feat, out_feat
244|    );
245|
246|    let raw_output: Vec<f32> = output_data
247|        .chunks_exact(4)
248|        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
249|        .collect();
250|
251|    // Transpose output weights
252|    let mut output_proj_weight = vec![0.0f32; out_feat * in_feat];
253|    for row in 0..in_feat {
254|        for col in 0..out_feat {
255|            output_proj_weight[col * in_feat + row] = raw_output[row * out_feat + col];
256|        }
257|    }
