12|pub trait GgufHeaderExt {
13|    fn attention_head_count_kv(&self) -> Option<u32>;
14|    fn rope_dimension_count(&self) -> Option<i32>;
15|    fn normalization_epsilon(&self) -> Option<f32>;
16|    fn vocab_size(&self) -> u32;
17|    fn get_kv_f32(&self, key: &str) -> Option<f32>;
18|    fn get_kv_bool(&self, key: &str) -> Option<bool>;
19|}
