21|impl GgufHeaderExt for GgufHeader {
22|    fn attention_head_count_kv(&self) -> Option<u32> {
23|        self.get_kv_u32("attention.head_count_kv")
24|            .or_else(|| self.get_kv_u32("attention.head_count"))
25|    }
26|
27|    fn rope_dimension_count(&self) -> Option<i32> {
28|        self.get_kv_u32("rope.dimension_count").map(|v| v as i32)
29|    }
