251|    /// Allocate zero-initialized memory on the given backend.
252|    pub fn zeros_device<B: MemoryBackend>(
253|        backend: &B,
254|        len: usize,
255|    ) -> Result<Self, DeviceBufferError>
256|    where
257|        T: Default + Copy,
258|    {
259|        let bytes = len * std::mem::size_of::<T>();
260|        let handle = backend
261|            .alloc(bytes)
262|            .map_err(|e| DeviceBufferError::Allocation(format!("alloc {} bytes: {e}", bytes)))?;
263|
264|        Ok(Self {
265|            handle,
266|            len,
267|            _marker: PhantomData,
268|            backed: true,
269|            host_data: None,
270|        })
271|    }
272|
273|    /// Copy device data to a host Vec.
274|    pub fn to_host_vec<B: MemoryBackend>(&self, backend: &B) -> Result<Vec<T>, DeviceBufferError>
275|    where
276|        T: Default + Copy,
277|    {
278|        let bytes = self.byte_len();
279|        let mut buf = vec![T::default(); self.len];
280|        let dst_bytes: &mut [u8] =
281|            unsafe { std::slice::from_raw_parts_mut(buf.as_mut_ptr() as *mut u8, bytes) };
282|        backend
283|            .d2h(self.handle, dst_bytes)
284|            .map_err(|e| DeviceBufferError::Transfer(format!("D2H: {e}")))?;
285|        Ok(buf)
286|    }
287|
288|    /// Copy device data to a pre-allocated host slice.
289|    pub fn to_host_slice<B: MemoryBackend>(
290|        &self,
291|        backend: &B,
292|        dst: &mut [T],
293|    ) -> Result<(), DeviceBufferError> {
294|        let bytes = self.byte_len();
295|        let dst_bytes: &mut [u8] =
296|            unsafe { std::slice::from_raw_parts_mut(dst.as_mut_ptr() as *mut u8, bytes) };
297|        backend
298|            .d2h(self.handle, dst_bytes)
299|            .map_err(|e| DeviceBufferError::Transfer(format!("D2H: {e}")))?;
300|        Ok(())
301|    }
302|
303|    /// Copy host data to this device buffer.
304|    pub fn from_host_slice<B: MemoryBackend>(
305|        &self,
306|        backend: &B,
307|        src: &[T],
308|    ) -> Result<(), DeviceBufferError>
309|    where
310|        T: Copy,
311|    {
312|        if src.len() != self.len {
313|            return Err(DeviceBufferError::SizeMismatch {
314|                expected: self.len,
315|                got: src.len(),
316|            });
317|        }
318|        let bytes = src.len() * std::mem::size_of::<T>();
319|        let src_bytes: &[u8] =
320|            unsafe { std::slice::from_raw_parts(src.as_ptr() as *const u8, bytes) };
321|        backend
322|            .h2d(src_bytes, self.handle)
323|            .map_err(|e| DeviceBufferError::Transfer(format!("H2D: {e}")))?;
324|        Ok(())
325|    }
326|
327|    /// Get a reference to the underlying data (host-backed only).
328|    ///
329|    /// Returns None for backend-allocated buffers — use `to_host_vec()`
330|    /// or `to_host_slice()` instead.
331|    pub fn as_slice(&self) -> Option<&[T]> {
332|        self.host_data.as_ref().map(|v| v.as_slice())
333|    }
334|
335|    /// Get the raw device pointer (if applicable).
336|    ///
337|    /// Returns the RawHandle's u64 value. For CPU backend this is the slab
338|    /// index; for CUDA backend this is the actual device pointer.
339|    pub fn device_ptr(&self) -> u64 {
340|        self.handle.0
341|    }
342|
343|    /// Allocate zero-initialized host-backed buffer (no backend needed).
344|    ///
345|    /// For CPU-only mode and testing. Does not go through MemoryBackend.
346|    pub fn zeros(len: usize) -> Self
347|    where
