147|// ============================================================================
148|// JSON-RPC Command Handler
149|// ============================================================================
150|
151|async fn handle_json_rpc_commands(state: std::sync::Arc<PluginState>) -> io::Result<()> {
152|    let stdin = io::stdin();
153|    let stdout = io::stdout();
154|    let mut reader = BufReader::new(stdin.lock());
155|    let mut output = stdout.lock();
156|
157|    eprintln!("DEBUG: JSON-RPC handler STARTED");
158|
159|    loop {
160|        // Read JSON-RPC request
161|        let mut line = String::new();
162|        match reader.read_line(&mut line) {
163|            Ok(0) => {
164|                eprintln!("DEBUG: EOF received, breaking");
165|                break;
166|            }
167|            Ok(_) => {}
168|            Err(e) => {
169|                eprintln!("DEBUG: read error: {}", e);
170|                continue;
171|            }
172|        }
173|
174|        eprintln!("DEBUG: received command: {}", line.trim());
175|
176|        let request: CommandRequest = match serde_json::from_str(&line) {
177|            Ok(r) => r,
178|            Err(e) => {
179|                let resp = CommandResponse {
180|                    id: 0,
181|                    result: None,
182|                    error: Some(format!("parse error: {}", e)),
183|                };
184|                writeln!(output, "{}", serde_json::to_string(&resp).unwrap()).unwrap();
185|                output.flush().unwrap();
186|                continue;
187|            }
188|        };
189|
190|        // Handle command - lock world and modify it
191|        let result = {
192|            let mut world_guard = state.world.lock().await;
193|            match request.method.as_str() {
194|                "terrarium/start" => {
195|                    world_guard.paused = false;
196|                    world_guard.tick = 1;
197|                    serde_json::to_value(command_handler::CommandResult::success("Terrarium started"))
198|                        .unwrap()
199|                }
200|                "terrarium/stop" => {
201|                    world_guard.paused = true;
202|                    serde_json::to_value(command_handler::CommandResult::success("Terrarium stopped"))
203|                        .unwrap()
204|                }
205|                "terrarium/pause" => {
206|                    world_guard.paused = true;
207|                    let event = GameEvent {
208|                        id: Uuid::new_v4().to_string(),
209|                        event_type: EventType::AgentCommand {
210|                            agent_id: "user".to_string(),
211|                            command: "pause".to_string(),
212|                            parameters: serde_json::json!({}),
213|                            success: true,
214|                        },
215|                        timestamp: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs(),
216|                        tick: world_guard.tick,
217|                        source: EventSource::User,
218|                        payload: crate::dagr_feed::EventPayload::AgentCommand {
219|                            agent_id: "user".to_string(),
220|                            command: "pause".to_string(),
221|                            parameters: serde_json::json!({}),
222|                            success: true,
223|                        },
224|                    };
225|                    println!("DAGR EVENT: {}", serde_json::to_string(&event).unwrap_or_default());
226|                    serde_json::to_value(command_handler::CommandResult::success("Paused"))
227|                        .unwrap()
228|                }
229|                "terrarium/resume" => {
230|                    world_guard.paused = false;
231|                    let event = GameEvent {
232|                        id: Uuid::new_v4().to_string(),
233|                        event_type: EventType::AgentCommand {
234|                            agent_id: "user".to_string(),
235|                            command: "resume".to_string(),
236|                            parameters: serde_json::json!({}),
237|                            success: true,
238|                        },
239|                        timestamp: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs(),
240|                        tick: world_guard.tick,
241|                        source: EventSource::User,
242|                        payload: crate::dagr_feed::EventPayload::AgentCommand {
243|                            agent_id: "user".to_string(),
244|                            command: "resume".to_string(),
245|                            parameters: serde_json::json!({}),
246|                            success: true,
247|                        },
248|                    };
249|                    println!("DAGR EVENT: {}", serde_json::to_string(&event).unwrap_or_default());
250|                    serde_json::to_value(command_handler::CommandResult::success("Resumed"))
251|                        .unwrap()
252|                }
253|                "terrarium/set_speed" => {
254|                    if let Some(params) = &request.params {
255|                        if let Some(val) = &params.value {
256|                            if let Ok(speed) = val.parse::<f32>() {
257|                                world_guard.speed = speed.max(0.1);
258|                                let event = GameEvent {
259|                                    id: Uuid::new_v4().to_string(),
260|                                    event_type: EventType::AgentCommand {
261|                                        agent_id: "user".to_string(),
262|                                        command: "set_speed".to_string(),
263|                                        parameters: serde_json::json!({"value":speed}),
264|                                        success: true,
265|                                    },
266|                                    timestamp: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs(),
267|                                    tick: world_guard.tick,
268|                                    source: EventSource::User,
269|                                    payload: crate::dagr_feed::EventPayload::AgentCommand {
270|                                        agent_id: "user".to_string(),
271|                                        command: "set_speed".to_string(),
272|                                        parameters: serde_json::json!({"value":speed}),
273|                                        success: true,
274|                                    },
275|                                };
276|                                println!("DAGR EVENT: {}", serde_json::to_string(&event).unwrap_or_default());
277|                                serde_json::to_value(command_handler::CommandResult::success(format!(
278|                                    "Speed set to {}x",
279|                                    world_guard.speed
280|                                )))
281|                                .unwrap()
282|                            } else {
283|                                serde_json::to_value(command_handler::CommandResult::failure(
284|                                    "Invalid speed value",
285|                                ))
286|                                .unwrap()
287|                            }
288|                        } else {
289|                            serde_json::to_value(command_handler::CommandResult::failure(
290|                                "Missing speed value",
291|                            ))
292|                            .unwrap()
293|                        }
294|                    } else {
295|                        serde_json::to_value(command_handler::CommandResult::failure(
296|                            "Missing params",
297|                        ))
298|                        .unwrap()
299|                    }
300|                }
301|                _ => {
302|                    serde_json::to_value(command_handler::CommandResult::failure(format!(
303|                        "Unknown method: {}",
304|                        request.method
305|                    )))
306|                    .unwrap()
307|                }
308|            }
309|        };
310|
311|        let response = CommandResponse {
312|            id: request.id,
313|            result: Some(result),
314|            error: None,
315|        };
316|
317|        writeln!(output, "{}", serde_json::to_string(&response).unwrap())?;
318|        output.flush()?;
319|    }
320|
321|    eprintln!("DEBUG: JSON-RPC handler EXITED");
322|    Ok(())
323|}
324|
325|async fn run_isometric_world_with_state(state: std::sync::Arc<PluginState>) {
326|    // Extract initial world snapshot for rendering
327|    let mut world = {
328|        let guard = state.world.lock().await;
329|        guard.clone()
330|    };
331|    
332|    // Set tick to start
333|    world.tick = 1;
334|    world.paused = false;
335|    
336|    eprintln!("DEBUG: isometric render loop STARTED with shared state");
337|    
338|    let mut last_paused = world.paused;
339|    let mut last_speed = world.speed;
340|    
341|    loop {
342|        // Check for state updates from commands
343|        {
344|            let guard = state.world.lock().await;
345|            if guard.paused != last_paused {
346|                world.paused = guard.paused;
347|                last_paused = world.paused;
348|            }
349|            if (guard.speed - last_speed).abs() > 0.01 {
350|                world.speed = guard.speed;
351|                last_speed = world.speed;
352|            }
353|        }
354|        
355|        // Update world tick if running
356|        if !world.paused {
357|            world.tick += 1;
358|            
359|            // Move entities
360|            for entity in &mut world.entities {
361|                entity.x += 0.05_f32 * world.speed;
362|                entity.y += 0.03_f32 * world.speed;
363|                
364|                if entity.x > 80.0 {
365|                    entity.x = 0.0;
366|                }
367|                if entity.y > 48.0 {
368|                    entity.y = 0.0;
369|                }
370|            }
371|            
372|            render_world(&world);
373|        } else {
374|            // Still render paused state
375|            render_world(&world);
376|        }
377|
378|        let sleep_ms = (50.0 / world.speed).max(10.0) as u64;
