263|// Game Loop Integration
264|// ============================================================================
265|
266|/// Main render loop for isometric terrarium
267|pub async fn run_isometric_world(mut world: GameWorld) {
268|    eprintln!("DEBUG: isometric render loop STARTED");
269|    
270|    let mut tick = 0u64;
271|    while world.tick > 0 || tick == 0 {
272|        if !world.paused {
273|            // Update world state
274|            world.tick += 1;
275|            
276|            // Move entities smoothly (simple interpolation) with DAGR emission
277|            use crate::dagr_feed::{EventSource, EventType, GameEvent};
278|            use uuid::Uuid;
279|            for entity in &mut world.entities {
280|                let old_x = entity.x;
281|                let old_y = entity.y;
282|                // Simple wandering behavior
283|                entity.x += 0.05_f32 * world.speed;
284|                entity.y += 0.03_f32 * world.speed;
285|                
286|                // Wrap around screen edges
287|                if entity.x > SCREEN_WIDTH as f32 {
288|                    entity.x = 0.0;
289|                }
290|                if entity.y > (SCREEN_HEIGHT * 2) as f32 {
291|                    entity.y = 0.0;
292|                }
293|                
294|                // Emit DAGR event if entity moved
295|                if (entity.x - old_x).abs() > 0.001 || (entity.y - old_y).abs() > 0.001 {
296|                    let event = GameEvent {
297|                        id: Uuid::new_v4().to_string(),
298|                        event_type: EventType::EntityMove {
299|                            entity_id: entity.id.clone(),
300|                            from_x: old_x,
301|                            from_y: old_y,
302|                            to_x: entity.x,
303|                            to_y: entity.y,
304|                            direction: None,
305|                        },
306|                        timestamp: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs(),
307|                        tick: world.tick,
308|                        source: EventSource::Simulation,
309|                        payload: crate::dagr_feed::EventPayload::EntityMove {
310|                            entity_id: entity.id.clone(),
311|                            from_x: old_x,
312|                            from_y: old_y,
313|                            to_x: entity.x,
314|                            to_y: entity.y,
315|                            direction: None,
316|                        },
317|                    };
318|                    eprintln!("DAGR EVENT: {}", serde_json::to_string(&event).unwrap_or_default());
319|                }
320|            }
321|            
322|            // Render frame
323|            render_world(&world);
324|        }
325|
326|        let sleep_ms = (50.0 / world.speed).max(10.0) as u64;
327|        tokio::time::sleep(tokio::time::Duration::from_millis(sleep_ms)).await; // speed-adjusted
328|    }
329|    
330|    eprintln!("DEBUG: isometric render loop EXITED");
331|}
