{"content": "1|//! Agent command handler for CrabJar isometric game.
2|//!
3|//! Parses JSON-RPC commands from agents and executes them in the game world.
4|
5|use crate::dagr_feed::{AgentCommand, GameAction, Direction, StructureType};
6|use crate::render_isometric::{Entity, GameWorld, IsometricTile, TileType};
7|use serde::{Deserialize, Serialize};
8|use serde_json::Value;
9|
10|// ============================================================================
11|// Command Handler
12|// ============================================================================
13|
14|/// Handles agent commands and executes them in the game world.
15|pub struct AgentCommandHandler {
16|    pub world: GameWorld,
17|}
18|
19|impl AgentCommandHandler {
20|    pub fn new(world: GameWorld) -> Self {
21|        Self { world }
22|    }
23|
24|    /// Execute a parsed agent command.
25|    pub fn execute_command(&mut self, command: AgentCommand) -> CommandResult {
26|        match command.action {
27|            GameAction::Move { entity_id, direction, ticks } => {
28|                self.execute_move(&entity_id, direction, ticks)
29|            }
30|            GameAction::Build { entity_id, tile_x, tile_y, structure_type, height } => {
31|                self.execute_build(&entity_id, tile_x, tile_y, structure_type, height)
32|            }
33|            GameAction::Interact { entity_id, target_id, action } => {
34|                self.execute_interact(&entity_id, &target_id, &action)
35|            }
36|        }
37|    }
38|
39|    /// Execute move command: move entity in direction for N ticks.
40|    fn execute_move(&mut self, entity_id: &str, direction: Direction, ticks: u64) -> CommandResult {
41|        let mut found = false;
42|        
43|        for entity in &mut self.world.entities {
44|            if entity.id == entity_id {
45|                found = true;
46|                
47|                // Calculate movement delta based on direction
48|                let (dx, dy) = match direction {
49|                    Direction::North => (0.0, -1.0),
50|                    Direction::South => (0.0, 1.0),
51|                    Direction::East => (1.0, 0.0),
52|                    Direction::West => (-1.0, 0.0),
53|                    Direction::Northeast => (0.707, -0.707), // ~45 degrees
54|                    Direction::Northwest => (-0.707, -0.707),
55|                    Direction::Southeast => (0.707, 0.707),
56|                    Direction::Southwest => (-0.707, 0.707),
57|                };
58|                
59|                // Apply movement for N ticks
60|                for _ in 0..ticks {
61|                    entity.x += dx;
62|                    entity.y += dy;
63|                    
64|                    // Wrap around screen edges
65|                    if entity.x > 80.0 {
66|                        entity.x = 0.0;
67|                    } else if entity.x < 0.0 {
68|                        entity.x = 79.0;
69|                    }
70|                    
71|                    if entity.y > 48.0 {
72|                        entity.y = 0.0;
73|                    } else if entity.y < 0.0 {
74|                        entity.y = 47.0;
75|                    }
76|                }
77|            }
78|        }
79|        
80|        if found {
81|            CommandResult::success(format!(
82|                "Moved {} {} for {} ticks",
83|                entity_id, direction_name(&direction), ticks
84|            ))
85|        } else {
86|            CommandResult::failure(format!("Entity '{}' not found", entity_id))
87|        }
88|    }
89|
90|    /// Execute build command: construct structure at tile coordinates.
91|    fn execute_build(
92|        &mut self,
93|        entity_id: &str,
94|        tile_x: i32,
95|        tile_y: i32,
96|        structure_type: StructureType,
97|        height: i32,
98|    ) -> CommandResult {
99|        // Find or create tile at coordinates
100|        let tile = self.world.tiles.iter_mut().find(|t| t.x == tile_x && t.y == tile_y);
101|        
102|        match tile {
103|            Some(tile) => {
104|                // Update tile type based on structure
105|                tile.tile_type = match structure_type {
106|                    StructureType::Wall => TileType::Stone,
107|                    StructureType::Tower => TileType::Stone,
108|                    StructureType::Bridge => TileType::Wood,
109|                    StructureType::Gate => TileType::Wood,
110|                    StructureType::ResourceNode => TileType::Grass,
111|                };
112|                tile.z = height; // Set height
113|                
114|                CommandResult::success(format!(
115|                    "Built {} at ({}, {}) with height {}",
116|                    structure_type_name(&structure_type), tile_x, tile_y, height
117|                ))
118|            }
119|            None => {
120|                // Create new tile if it doesn't exist
121|                let new_tile = IsometricTile {
122|                    x: tile_x,
123|                    y: tile_y,
124|                    z: height,
125|                    tile_type: TileType::Grass, // Default to grass
126|                };
127|                
128|                self.world.tiles.push(new_tile);
129|                
130|                CommandResult::success(format!(
131|                    "Created new tile at ({}, {}) with {}",
132|                    tile_x, tile_y, structure_type_name(&structure_type)
133|                ))
134|            }
135|        }
136|    }
137|
138|    /// Execute interact command: perform interaction between entities.
139|    fn execute_interact(
140|        &mut self,
141|        entity_id: &str,
142|        target_id: &str,
143|        action: &str,
144|    ) -> CommandResult {
145|        let entity = self.world.entities.iter().find(|e| e.id == entity_id);
146|        let target = self.world.entities.iter().find(|e| e.id == target_id);
147|        
148|        match (entity, target) {
149|            (Some(_), Some(_)) => {
150|                // Calculate distance between entities
151|                let dx = entity.unwrap().x - target.unwrap().x;
152|                let dy = entity.unwrap().y - target.unwrap().y;
153|                let distance = (dx * dx + dy * dy).sqrt();
154|                
155|                if distance < 5.0 {
156|                    CommandResult::success(format!(
157|                        "{} interacted with {} ({:.1} units away)",
158|                        entity_id, target_id, distance
159|                    ))
160|                } else {
161|                    CommandResult::failure(format!(
162|                        "{} and {} too far apart (distance: {:.1})",
163|                        entity_id, target_id, distance
164|                    ))
165|                }
166|            }
167|            (None, _) => CommandResult::failure(format!("Entity '{}' not found", entity_id)),
168|            (_, None) => CommandResult::failure(format!("Target '{}' not found", target_id)),
169|        }
170|    }
171|
172|    /// Parse and execute command from JSON string.
173|    pub fn execute_from_json(&mut self, json: &str) -> CommandResult {
174|        match serde_json::from_str(json) {
175|            Ok(command) => self.execute_command(command),
176|            Err(e) => CommandResult::parse_error(e.to_string()),
177|        }
178|    }
179|
180|    /// Get current world state for event generation.
181|    pub fn get_world_state(&self) -> &GameWorld {
182|        &self.world
183|    }
184|}
185|
186|// ============================================================================
187|// Result Types
188|// ============================================================================
189|
190|/// Result of command execution.
191|#[derive(Debug, Clone, Serialize)]
192|pub struct CommandResult {
193|    pub success: bool,
194|    pub message: String,
195|    #[serde(skip_serializing_if = "Option::is_none")]
196|    pub details: Option<CommandDetails>,
197|}
198|
199|impl CommandResult {
200|    pub fn success(message: impl Into<String>) -> Self {
201|        Self {
202|            success: true,
203|            message: message.into(),
204|            details: None,
205|        }
206|    }
207|
208|    pub fn failure(message: impl Into<String>) -> Self {
209|        Self {
210|            success: false,
211|            message: message.into(),
212|            details: None,
213|        }
214|    }
215|
216|    pub fn parse_error(message: impl Into<String>) -> Self {
217|        Self {
218|            success: false,
219|            message: format!("Parse error: {}", message.into()),
220|            details: None,
221|        }
222|    }
223|
224|    pub fn with_details(mut self, details: CommandDetails) -> Self {
225|        self.details = Some(details);
226|        self
227|    }
228|}
229|
230|/// Optional details for successful commands.
231|#[derive(Debug, Clone, Serialize)]
232|pub struct CommandDetails {
233|    pub entity_id: Option<String>,
234|    pub tile_x: Option<i32>,
235|    pub tile_y: Option<i32>,
236|    pub new_position: Option<(f32, f32)>,
237|}
238|
239|// ============================================================================
240|// Helper Functions
241|// ============================================================================
242|
243|fn direction_name(d: &Direction) -> &'static str {
244|    match d {
245|        Direction::North => "north",
246|        Direction::South => "south",
247|        Direction::East => "east",
248|        Direction::West => "west",
249|        Direction::Northeast => "northeast",
250|        Direction::Northwest => "northwest",
251|        Direction::Southeast => "southeast",
252|        Direction::Southwest => "southwest",
253|    }
254|}
255|
256|fn structure_type_name(s: &StructureType) -> &'static str {
257|    match s {
258|        StructureType::Wall => "wall",
259|        StructureType::Tower => "tower",
260|        StructureType::Bridge => "bridge",
261|        StructureType::Gate => "gate",
262|        StructureType::ResourceNode => "resource_node",
263|    }
264|}
265|
266|// ============================================================================
267|// JSON-RPC Request Wrapper
268|// ============================================================================
269|
270|/// Standard JSON-RPC 2.0 request format for agent commands.
271|#[derive(Debug, Deserialize)]
272|pub struct JsonRpcRequest {
273|    pub jsonrpc: String,
274|    pub id: u64,
275|    pub method: String,
276|    pub params: Value,
277|}
278|
279|impl JsonRpcRequest {
280|    /// Extract agent command from JSON-RPC request.
281|    pub fn to_agent_command(&self) -> Result<AgentCommand, serde_json::Error> {
282|        // The params should contain the agent command structure
283|        // This depends on how agents send commands
284|        serde_json::from_value(self.params.clone())
285|    }
