{"content": "1|//! The terrarium world model — pure grid data, no rendering.
2|//!
3|//! This is the inside of the glass: cells, crabs, and their movement are
4|//! plain data. The presentation layer (ratty/RGP) reads this and emits
5|//! sequences; it never mutates it. Swapping the renderer later means writing
6|//! a new reader over this same state — the world logic does not change.
7|//!
8|//! Movement is *gliding*: each crab holds a fractional position that advances
9|//! toward its target cell at a fixed speed, so a renderer can place it
10|//! sub-cell (the RGP layer does this with `px`/`py` offsets). The world is
11|//! renderer-agnostic — it only knows the fractional position, not pixels.
12|
13|/// Speed at which a crab glides toward its target, in cells per second.
14|const GLIDE_SPEED: f32 = 2.5;
15|
16|/// Distance (in cells) below which a crab counts as arrived at its target.
17|const ARRIVE_EPS: f32 = 1e-3;
18|
19|/// A crab wandering the grid.
20|#[derive(Debug, Clone)]
21|pub struct Crab {
22|    /// Stable RGP object id (also the crab's identity).
23|    pub id: u32,
24|    /// Fractional current column (sub-cell, for gliding).
25|    pub pos_col: f32,
26|    /// Fractional current row (sub-cell, for gliding).
27|    pub pos_row: f32,
28|    /// Target cell column the crab is heading toward.
29|    pub target_col: u16,
30|    /// Target cell row.
31|    pub target_row: u16,
32|    /// RGB color for placement.
33|    pub color: [u8; 3],
34|    /// Animation phase (radians-ish), advanced each tick.
35|    pub phase: f32,
36|    /// Seconds until the crab takes its next step.
37|    move_in: f32,
38|}
39|
40|/// The grid world.
41|#[derive(Debug)]
42|pub struct World {
43|    /// Grid width in cells.
44|    pub width: u16,
45|    /// Grid height in cells.
46|    pub height: u16,
47|    /// Crabs living in the grid.
48|    pub crabs: Vec<Crab>,
49|    rng: u64,
50|    /// Monotonic tick counter (for the HUD).
51|    pub ticks: u64,
52|    /// Paused state — skip updates when true.
53|    pub paused: bool,
54|}
55|
56|impl World {
57|    /// Create a world of `width`x`height` cells with `crab_count` crabs.
58|    #[must_use]
59|    pub fn new(width: u16, height: u16, crab_count: usize) -> Self {
60|        let mut rng: u64 = 0x9E37_79B9_7F4A_7C15;
61|        let palette: [[u8; 3]; 8] = [
62|            [255, 120, 60],
63|            [90, 200, 255],
64|            [120, 255, 140],
65|            [255, 220, 90],
66|            [255, 90, 180],
67|            [180, 130, 255],
68|            [230, 230, 230],
69|            [120, 220, 200],
70|        ];
71|        let mut crabs = Vec::with_capacity(crab_count);
72|        for i in 0..crab_count {
73|            let col = next_in_range(&mut rng, 0, width.saturating_sub(1));
74|            let row = next_in_range(&mut rng, 0, height.saturating_sub(1));
75|            crabs.push(Crab {
76|                id: 1000 + i as u32,
77|                pos_col: col as f32,
78|                pos_row: row as f32,
79|                target_col: col,
80|                target_row: row,
81|                color: palette[i % palette.len()],
82|                phase: i as f32 * 0.7,
83|                move_in: next_f32(&mut rng, 0.1, 0.8),
84|            });
85|        }
86|        Self {
87|            width,
88|            height,
89|            crabs,
90|            rng,
91|            ticks: 0,
92|            paused: false,
93|        }
94|    }
95|
96|    /// Advance the world by `delta` seconds.
97|    pub fn tick(&mut self, delta: f32) {
98|        if self.paused { return; }
99|        self.ticks += 1;
100|        let width = self.width;
101|        let height = self.height;
102|        let mut rng = self.rng;
103|        for crab in &mut self.crabs {
104|            crab.phase += delta * 3.0;
105|            if crab.move_in > 0.0 {
106|                crab.move_in -= delta;
107|                continue;
108|            }
109|            let arrived = crab.at_target();
110|            if arrived {
111|                // Rest a beat, then pick a new neighbor to glide toward.
112|                pick_neighbor_target(crab, &mut rng, width, height);
113|                crab.move_in = next_f32(&mut rng, 0.25, 0.7);
114|            } else {
115|                glide_toward(crab, delta);
116|                // Keep moving until the glide completes.
117|                crab.move_in = 0.0;
118|            }
119|        }
120|        self.rng = rng;
121|    }
122|
123|    /// Fast tick mode (10x speed) for + key
124|    pub fn tick_fast(&mut self) {
125|        for _ in 0..10 {
126|            self.tick(0.033); // Same as normal delta * 10
127|        }
128|    }
129|
130|    /// Slow tick mode (0.5x speed) for - key
131|    pub fn tick_slow(&mut self) {
132|        self.tick(0.016); // Half the normal delta
133|    }
134|
135|    /// Number of crabs.
136|    #[must_use]
137|    pub fn crab_count(&self) -> usize {
138|        self.crabs.len()
139|    }
140|
141|    /// Toggle paused state.
142|    pub fn toggle_pause(&mut self) {
143|        self.paused = !self.paused;
144|    }
145|
146|    /// Step forward one tick (for manual control).
147|    pub fn step(&mut self) {
148|        self.tick(0.033); // Single normal delta
149|    }
150|}
151|
152|impl Crab {
153|    /// Whether the crab is (effectively) at its target cell.
154|    #[must_use]
155|    pub fn at_target(&self) -> bool {
156|        (self.pos_col - self.target_col as f32).abs() < ARRIVE_EPS
157|            && (self.pos_row - self.target_row as f32).abs() < ARRIVE_EPS
158|    }
159|}
160|
161|/// Advance the crab's fractional position toward its target at GLIDE_SPEED.
162|/// The final step snaps exactly onto the target so the glide never overshoots.
163|fn glide_toward(crab: &mut Crab, delta: f32) {
164|    let step = GLIDE_SPEED * delta;
165|    let tx = crab.target_col as f32;
166|    let ty = crab.target_row as f32;
167|
168|    let dc = tx - crab.pos_col;
169|    let dr = ty - crab.pos_row;
170|    if dc.abs() <= step {
171|        crab.pos_col = tx;
172|    } else {
173|        crab.pos_col += dc.signum() * step;
174|    }
175|    if dr.abs() <= step {
176|        crab.pos_row = ty;
177|    } else {
178|        crab.pos_row += dr.signum() * step;
179|    }
180|}
181|
182|/// Pick a random in-bounds 4-neighbor as the crab's new target.
183|fn pick_neighbor_target(crab: &mut Crab, rng: &mut u64, width: u16, height: u16) {
184|    const DIRS: [(i32, i32); 4] = [(1, 0), (-1, 0), (0, 1), (0, -1)];
185|    for _ in 0..8 {
186|        let (sx, sy) = DIRS[next_in_range(rng, 0, 3) as usize];
187|        let nx = crab.target_col as i32 + sx;
188|        let ny = crab.target_row as i32 + sy;
189|        if nx >= 0 && nx < width as i32 && ny >= 0 && ny < height as i32 {
190|            crab.target_col = nx as u16;
191|            crab.target_row = ny as u16;
192|            return;
193|        }
194|    }
195|}
196|
197|// Deterministic LCG helpers — no `rand` dependency for a first cut.
198|
199|fn lcg(rng: &mut u64) -> u64 {
200|    *rng = rng
201|        .wrapping_mul(6364136223846793005)
202|        .wrapping_add(1442695040888963407);
203|    *rng >> 32
204|}
205|
206|fn next_in_range(rng: &mut u64, lo: u16, hi: u16) -> u16 {
207|    let span = hi.saturating_sub(lo).max(1) as u64;
208|    lo + (lcg(rng) % span) as u16
209|}
210|
211|fn next_f32(rng: &mut u64, lo: f32, hi: f32) -> f32 {
212|    lo + ((lcg(rng) % 1000) as f32 / 1000.0) * (hi - lo)
213|}
214|
215|#[cfg(test)]
216|mod tests {
217|    use super::*;
218|
219|    #[test]
220|    fn world_starts_with_requested_crab_count() {
221|        let w = World::new(20, 12, 6);
222|        assert_eq!(w.crab_count(), 6);
223|        assert_eq!(w.width, 20);
224|        assert_eq!(w.height, 12);
225|    }
226|
227|    #[test]
228|    fn crabs_stay_in_bounds_over_many_ticks() {
229|        let mut w = World::new(10, 8, 5);
230|        for _ in 0..5000 {
231|            w.tick(0.1);
232|        }
233|        for c in &w.crabs {
234|            assert!(c.pos_col >= 0.0 && c.pos_col < w.width as f32);
235|            assert!(c.pos_row >= 0.0 && c.pos_row < w.height as f32);
236|        }
237|    }
238|
239|    #[test]
240|    fn crabs_eventually_move() {
241|        let mut w = World::new(12, 10, 4);
242|        let start: Vec<(f32, f32)> = w
243|            .crabs
244|            .iter()
245|            .map(|c| (c.pos_col, c.pos_row))
246|            .collect();
247|        for _ in 0..2000 {
248|            w.tick(0.1);
249|        }
250|        let moved = w
251|            .crabs
252|            .iter()
253|            .zip(start.iter())
254|            .filter(|(c, s)| (c.pos_col, c.pos_row) != **s)
255|            .count();
256|        assert!(moved > 0, "at least one crab should have moved");
257|    }
258|
259|    #[test]
260|    fn glide_reaches_target_exactly() {
261|        let mut w = World::new(8, 8, 1);
262|        let c = &mut w.crabs[0];
263|        c.pos_col = 1.0;
264|        c.pos_row = 1.0;
265|        c.target_col = 4;
266|        c.target_row = 3;
267|        c.move_in = 0.0;
268|        // Run until it arrives (bounded to avoid a hang in a regression).
269|        for _ in 0..1000 {
270|            if c.at_target() {
271|                break;
272|            }
273|            w.tick(0.1);
274|        }
275|        assert!(c.at_target(), "crab should land on its target");
276|        assert_eq!(c.pos_col, 4.0);
277|        assert_eq!(c.pos_row, 3.0);
278|    }
279|
280|    #[test]
281|    fn glide_is_subcell_between_ticks() {
282|        let mut w = World::new(8, 8, 1);
283|        let c = &mut w.crabs[0];
284|        c.pos_col = 1.0;
285|        c.pos_row = 1.0;
286|        c.target_col = 5;
287|        c.target_row = 1;
288|        c.move_in = 0.0;
289|        w.tick(0.1);
290|        // One tick at 2.5 cells/s moves 0.25 cells — strictly between start and target.
291|        assert!(c.pos_col > 1.0 && c.pos_col < 5.0, "should be mid-glide");
292|        assert!((c.pos_col - 1.25).abs() < 1e-3, "expected ~0.25 cell step");
293|    }
