+            entity.y = 0.0;
+            entity.vy = entity.vy.abs();
+        } else if entity.y > world.height as f32 {
+            entity.y = world.height as f32;
+            entity.vy = -entity.vy.abs();
+        }
+
+        any_moved = true;
+    }
+    any_moved
