152|impl Behaviors {
153|    /// Load a taste file. Missing file → the built-in default (the terrarium
154|    /// must never blank because the user hasn't tuned their taste yet).
155|    pub fn load(path: &std::path::Path) -> Self {
156|        match std::fs::read_to_string(path) {
157|            Ok(raw) => toml::from_str(&raw).unwrap_or_else(|e| {
158|                eprintln!("warning: bad behaviors.toml ({e}); using built-in taste");
159|                Self::default()
160|            }),
161|            Err(_) => Self::default(),
162|        }
163|    }
164|
165|    /// Map an effective state to a behavior. Unknown states → `wait` (never
166|    /// crash on a taste change, spec §5).
167|    pub fn behavior_for(&self, effective_state: &str) -> String {
168|        self.behavior
169|            .get(effective_state)
170|            .cloned()
171|            .unwrap_or_else(|| "wait".to_string())
172|    }
173|
174|    /// Map an evidence tier to its certainty signal. Unknown tiers → `reported`.
175|    pub fn evidence_for(&self, tier: &str) -> EvidenceSignal {
176|        self.evidence
177|            .get(tier)
178|            .or_else(|| self.evidence.get("reported"))
179|            .cloned()
180|            .unwrap_or(EvidenceSignal {
181|                tint: "amber".to_string(),
182|                posture: "neutral".to_string(),
183|            })
184|    }
