186|    /// Resolve a project id to its zone. Unmapped projects (and run-root tasks
187|    /// with no project) fall into the `root` zone, else a derived default.
188|    pub fn zone_for(&self, project: Option<&str>) -> (String, Zone) {
189|        let key = project.unwrap_or("root").to_string();
190|        if let Some(z) = self.zone.get(&key) {
191|            return (key, z.clone());
192|        }
193|        // Unmapped project: synthesize a zone from its id so it still renders.
194|        (
195|            key,
196|            Zone {
197|                label: None,
198|                x: 0,
199|                y: 0,
200|            },
201|        )
202|    }
203|
204|    /// Station glyph for a behavior, with a derived default.
205|    pub fn station_glyph(&self, behavior: &str) -> String {
206|        self.station
207|            .get(behavior)
208|            .map(|s| s.glyph.clone())
209|            .unwrap_or_else(|| "·".to_string())
