2|
3|use std::path::PathBuf;
4|
5|use crossterm::{
6|    event::{self, Event, KeyCode, KeyEventKind},
7|    execute,
8|    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
9|};
10|use ratatui::{
11|    backend::CrosstermBackend,
12|    layout::{Constraint, Direction, Layout, Rect},
13|    style::{Color, Modifier, Style},
14|    text::{Line, Span, Text},
15|    widgets::{Block, Borders, Paragraph},
16|    Frame, Terminal,
17|};
18|
19|use crate::contract::Run;
20|use crate::mapping::Behaviors;
21|use crate::simulator::{self, Crab, Habitat};
22|
23|pub struct TerrariumApp {
24|    contract_path: PathBuf,
25|    behaviors_path: Option<PathBuf>,
26|    run: Run,
27|    taste: Behaviors,
28|    habitat: Habitat,
29|    tidings_scroll: usize,
30|    running: bool,
31|}
32|
33|impl TerrariumApp {
34|    pub fn new(contract_path: PathBuf, behaviors_path: Option<PathBuf>) -> Self {
35|        let run = Run::load(&contract_path).expect("contract load");
36|        let taste = match &behaviors_path {
37|            Some(p) => Behaviors::load(p),
38|            None => Behaviors::default(),
39|        };
40|        let habitat = simulator::simulate(&run, &taste);
41|        Self {
42|            contract_path,
43|            behaviors_path,
44|            run,
45|            taste,
46|            habitat,
47|            tidings_scroll: 0,
48|            running: true,
49|        }
50|    }
51|
52|    pub fn reload(&mut self) {
53|        let run = Run::load(&self.contract_path).expect("contract load");
54|        let taste = match &self.behaviors_path {
55|            Some(p) => Behaviors::load(p),
56|            None => Behaviors::default(),
57|        };
58|        self.run = run;
59|        self.taste = taste;
60|        self.habitat = simulator::simulate(&self.run, &self.taste);
61|    }
62|
63|    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
64|        enable_raw_mode()?;
65|        let mut stdout = std::io::stdout();
66|        execute!(stdout, EnterAlternateScreen)?;
67|        let backend = CrosstermBackend::new(stdout);
68|        let mut terminal = Terminal::new(backend)?;
69|
70|        let res = self.run_terminal(&mut terminal);
71|        disable_raw_mode()?;
72|        execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
73|        terminal.show_cursor()?;
74|        res
75|    }
76|
77|    fn run_terminal(
78|        &mut self,
79|        terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
80|    ) -> Result<(), Box<dyn std::error::Error>> {
81|        while self.running {
82|            terminal.draw(|f| self.ui(f))?;
83|            if event::poll(std::time::Duration::from_millis(50))? {
84|                if let Event::Key(key) = event::read()? {
85|                    if key.kind == KeyEventKind::Press {
86|                        match key.code {
87|                            KeyCode::Char('q') => self.running = false,
88|                            KeyCode::Char('r') => self.reload(),
89|                            KeyCode::Up | KeyCode::Char('k') => {
90|                                self.tidings_scroll = self.tidings_scroll.saturating_sub(1);
91|                            }
92|                            KeyCode::Down | KeyCode::Char('j') => {
93|                                self.tidings_scroll = self.tidings_scroll.saturating_add(1);
94|                            }
95|                            _ => {}
96|                        }
97|                    }
98|                }
99|            }
100|        }
101|        Ok(())
102|    }
103|
104|    fn ui(&mut self, f: &mut Frame) {
105|        let title = self.run.run.title.clone().unwrap_or_else(|| "terrarium".to_string());
106|
107|        let chunks = Layout::default()
108|            .direction(Direction::Horizontal)
109|            .constraints([Constraint::Percentage(70), Constraint::Percentage(30)])
110|            .split(f.area());
111|
112|        let iso_area = chunks[0];
113|        f.render_widget(IsometricView { habitat: &self.habitat }, iso_area);
114|
115|        let tidings_lines: Vec<Line<'_>> = self
116|            .habitat
117|            .tidings
118|            .iter()
119|            .rev()
120|            .skip(self.tidings_scroll)
121|            .take(10)
122|            .map(|t| Line::from(Span::raw(t)))
123|            .collect();
124|
125|        let ticker = Paragraph::new(Text::from(tidings_lines))
126|            .block(Block::default().title(" tidings (j/k to scroll, r to reload) ").borders(Borders::ALL))
127|            .scroll((self.tidings_scroll as u16, 0));
128|
129|        f.render_widget(ticker, chunks[1]);
130|
131|        let title_bar = Paragraph::new(format!(
132|            " 🦀 {} · {} crabs · {} zones · generated {} ",
133|            title,
134|            self.habitat.crabs.len(),
135|            self.habitat.zones.len(),
136|            self.run.generated_at.as_deref().unwrap_or("?")
137|        ))
138|        .style(Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))
139|        .block(Block::default().borders(Borders::ALL).title(" terrarium "));
140|
141|        let title_area = Rect::new(0, 0, f.area().width, 1);
142|        f.render_widget(title_bar, title_area);
143|    }
