116|
117|    /// Render the habitat headlessly and return the buffer.
118|    fn render_habitat(run: &Run) -> Buffer {
119|        let taste = Behaviors::default();
120|        let habitat = simulator::simulate(run, &taste);
121|
122|        // Create a large canvas to hold the isometric view (crabs can spread out significantly)
123|        // The iso transform formula (x-y)*1 and (x+y)/2 means we need room for both dimensions
124|        let area = Rect::new(0, 0, 160, 60);
125|        let mut buf = Buffer::empty(area);
126|
127|        // Render the IsometricView widget (we need to import this from ui module)
128|        use crate::ui::IsometricView;
129|        let view = IsometricView { habitat: &habitat };
130|        view.render(area, &mut buf);
131|
132|        buf
133|    }
134|
135|    /// Assert that no two crabs occupy the same cell.
136|    ///
137|    /// This is the core finding #3 from the adversarial review: a small model can
138|    /// "fix" station offsets but stack multiple crabs on the same cell, which only
139|    /// human eyes would catch without this test.
140|    #[test]
141|    fn crabs_do_not_stack_on_same_cell() {
142|        let run = demo_contract();
143|        let buf = render_habitat(&run);
144|
145|        // Collect all cells that contain a crab (🦀) or a station glyph
146|        let mut occupied: Vec<(u16, u16)> = Vec::new();
147|        for y in 0..buf.area.height {
148|            for x in 0..buf.area.width {
149|                let cell = &buf[(x, y)];
150|                let ch = cell.symbol();
151|                // Crabs use 🦀 (U+1F980), stations use ▓ or other glyphs
152|                if ch == "🦀" || ch == "▓" || ch == "┌" {
153|                    occupied.push((x, y));
154|                }
155|            }
156|        }
157|
158|        // Check for duplicates
159|        let mut seen = std::collections::HashSet::new();
160|        for pos in &occupied {
161|            assert!(
162|                seen.insert(*pos),
163|                "Crab/station collision at {:?}: {} crabs occupy same cell",
164|                pos,
165|                occupied.iter().filter(|&p| p == pos).count()
166|            );
167|        }
168|
169|        // Also assert we have at least some crab cells (sanity check)
170|        let crab_count = occupied
171|            .iter()
172|            .map(|(x, y)| buf[(*x, *y)].symbol())
173|            .filter(|ch| *ch == "🦀")
174|            .count();
175|
176|        assert!(crab_count > 0, "No crab glyphs found in rendered buffer");
177|    }
178|
179|    /// Assert that crabs from the same zone spread across multiple columns.
180|    ///
181|    /// Finding #3 also covers: when a zone has 2+ tasks, they should occupy distinct
182|    /// horizontal positions (not all stacked at column X). This test verifies the
183|    /// iso transform is producing spatial distribution.
184|    #[test]
185|    fn crabs_in_same_zone_have_distinct_columns() {
186|        let run = demo_contract();
187|        let buf = render_habitat(&run);
188|
189|        // Collect all crab positions first
190|        let mut crab_positions: Vec<(u16, u16)> = Vec::new();
191|        for y in 0..buf.area.height {
192|            for x in 0..buf.area.width {
193|                if buf[(x, y)].symbol() == "🦀" {
194|                    crab_positions.push((x, y));
195|                }
196|            }
197|        }
198|
199|        // Extract columns and check for distinctness
200|        let cols: Vec<u16> = crab_positions.iter().map(|(x, _)| *x).collect();
201|        let distinct_cols: std::collections::HashSet<_> = cols.iter().cloned().collect();
202|
203|        assert!(
204|            distinct_cols.len() >= 2,
205|            "Crabs should occupy ≥2 distinct columns (iso transform bug?), got {}",
206|            distinct_cols.len()
207|        );
208|    }
209|
210|    /// Assert that the iso transform produces vertical spread (not everything on row 0).
