{"content": "1|//! Trait-based linear layer with automatic CPU/GPU dispatch.
2|//!
3|//! This module provides a unified `LinearLayer` trait that abstracts away
4|//! the device-specific implementation details. Callers interact with the
5|//! trait interface and don't need to know whether computation happens on
6|//! CPU or GPU.
7|
8|use crate::error::{Result, RunnerError};
9|use std::sync::Arc;
10|
11|/// Linear layer trait — the unified interface for all linear operations.
12|pub trait LinearLayer: Send + Sync {
13|    /// Forward pass: y = x @ W^T + bias
14|    fn forward(&self, x: &[f32], batch_size: usize) -> Result<Vec<f32>>;
15|
16|    /// Input dimensionality
17|    fn in_features(&self) -> usize;
18|
19|    /// Output dimensionality
20|    fn out_features(&self) -> usize;
21|
22|    /// Clone this layer (for model cloning scenarios).
23|    fn clone_layer(&self) -> Box<dyn LinearLayer>;
24|
25|    /// Upload weights to GPU (no-op for CPU-only layers).
26|    fn upload_weights_to_gpu(&mut self) -> Result<()> {
27|        Ok(())
28|    }
29|
30|    /// Check if weights are currently resident on GPU.
31|    fn weights_on_gpu(&self) -> bool {
32|        false
33|    }
34|
35|    /// Layer name for debugging/logging.
36|    fn layer_name(&self) -> &str {
37|        "linear"
38|    }
39|}
40|
41|/// Factory function that selects CPU vs GPU based on runtime availability.
42|pub fn new_linear_layer(
