78|/// CPU implementation using rayon-parallel matmul.
79|pub struct CpuLinearLayer {
80|    weight: Vec<f32>,
81|    bias: Option<Vec<f32>>,
82|    in_features: usize,
83|    out_features: usize,
84|}
85|
86|impl CpuLinearLayer {
87|    pub fn from_f32(
88|        weight: Vec<f32>,
89|        bias: Option<Vec<f32>>,
90|        in_features: usize,
91|        out_features: usize,
92|    ) -> Self {
93|        Self {
94|            weight,
95|            bias,
96|            in_features,
97|            out_features,
98|        }
99|    }
100|}
101|
102|impl LinearLayer for CpuLinearLayer {
103|    fn forward(&self, x: &[f32], batch_size: usize) -> Result<Vec<f32>> {
104|        let m = batch_size;
105|        let k = self.in_features;
106|        let n = self.out_features;
107|
108|        if x.len() < m * k {
109|            return Err(RunnerError::Kernel(format!(
110|                "linear layer input too small: expected {} values, got {}",
111|                m * k,
112|                x.len()
113|            )));
114|        }
115|
116|        let mut output = vec![0.0f32; m * n];
117|
118|        use rayon::prelude::*;
119|
120|        output
121|            .par_chunks_mut(n)
122|            .enumerate()
123|            .for_each(|(b, out_row)| {
124|                let x_start = b * k;
125|                for o in 0..n {
126|                    let w_row = &self.weight[o * k..(o + 1) * k];
127|                    let mut acc = 0.0f32;
128|                    for i in 0..k {
129|                        acc += x[x_start + i] * w_row[i];
130|                    }
131|                    out_row[o] = acc;
132|                }
133|            });
134|
135|        if let Some(ref bias) = self.bias {
136|            for b in 0..m {
137|                for o in 0..n {
138|                    output[b * n + o] += bias[o];
139|                }
140|            }
141|        }
142|
143|        Ok(output)
144|    }
